for method,check in [('animation-anchors','shading-drift-mask'),('frame-timing','frame-boundaries'),('silhouette-readability','key-silhouette-landmarks')]:
 c=json.loads((out/f'pixl_context-{method}.json').read_text(encoding='utf-8'));w=c['wire'];line=next(l for l in w.splitlines() if l.startswith('@e.'));dg=re.search(r';dg=~64:([a-f0-9]{64});md=',line).group(1);ur=re.search(r';ur=~\d+:([^}]+)',line).group(1)
 matches=[]
 for p in out.glob('poc-*.json'):
  d=json.loads(p.read_text(encoding='utf-8'))
  if '"id": "'+check+'"' in d['text']: matches.append({'path':p.as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'receipt_digest_matches_context':d['sha256']==dg})
 rows.append({'method':method,'check_id':check,'E_ur':ur,'E_dg':dg,'saved_slices':matches})
print(json.dumps(rows,indent=2));(out/'caller-receipt-verification.json').write_text(json.dumps(rows,indent=2))
'@ | python -","max_output_tokens":2000}));

